using CodoMetis.EFCore.SchemaKit.PostgreSQL.Tests.Harness;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.EntityFrameworkCore.Migrations.Operations;

namespace CodoMetis.EFCore.SchemaKit.PostgreSQL.Tests.Legacy;

/// <summary>
/// A migration 5.x scaffolded, generated by the context's own SQL generator (#110). What the
/// published 5.6.0 wrote is SQL and plain operations, and passes; what 5.0.1 wrote for a temporal
/// constraint is an operation only 5.x's generator rendered, and is refused where Npgsql's would
/// write a plain unique constraint. The kernel's tests hold the guard on every provider; these hold
/// it on the files a consumer has, through the package's own wiring.
/// </summary>
[TestClass]
public sealed class LegacyReplayTests
{
    private static string Script(IReadOnlyList<MigrationOperation> operations)
    {
        using var context = LegacyFixture.Context<MovedModels.SlotAlone>();
        return string.Join("\n", context.GetService<IMigrationsSqlGenerator>().Generate(operations).Select(c => c.CommandText));
    }

    [TestMethod]
    public void The_migration_5_6_0_scaffolded_for_exclusion_constraints_is_generated()
    {
        var up = Script(LegacyFixture.Up);

        StringAssert.Contains(up, "EXCLUDE USING gist");
        StringAssert.Contains(Script(LegacyFixture.Down), "DROP TABLE");
    }

    [TestMethod]
    public void The_migration_5_6_0_scaffolded_for_the_other_kinds_is_generated()
    {
        var (up, down) = LegacyFixture.OtherKindsMigration;
        var script = Script(up);

        // The temporal constraint as 5.6.0 wrote it at design time, and the two plain indexes.
        StringAssert.Contains(script, """ALTER TABLE "Tariff" ADD CONSTRAINT "AK_Tariff_ProductId_Valid" UNIQUE ("ProductId", "Valid" WITHOUT OVERLAPS);""");
        StringAssert.Contains(script, """CREATE INDEX "IX_Customer_Address_City" ON "Customer" ("Address_City");""");
        StringAssert.Contains(script, """CREATE UNIQUE INDEX "IX_Supplier_Address_Zip" ON "Supplier" ("Address_Zip");""");
        StringAssert.Contains(Script(down), "DROP TABLE");
    }

    /// <summary>The same constraint as 5.0.1 scaffolded it: the fixture's migration with that one statement as it was then.</summary>
    [TestMethod]
    public void The_same_migration_with_the_temporal_constraint_as_5_0_1_scaffolded_it_is_refused()
    {
        var early = new AddUniqueConstraintOperation { Table = "Tariff", Name = "AK_Tariff_ProductId_Valid", Columns = ["ProductId", "Valid"] };
        early.AddAnnotation("CustomTemporal:WithoutOverlaps", "Valid");
        var up = LegacyFixture.OtherKindsMigration.Up;
        Assert.IsInstanceOfType<SqlOperation>(up[^1], "The premise: the temporal constraint is the migration's last operation.");

        var refused = Assert.ThrowsExactly<InvalidOperationException>(() => Script([.. up.Take(up.Count - 1), early]));

        StringAssert.Contains(refused.Message,
            "The migration holds AddUniqueConstraintOperation 'AK_Tariff_ProductId_Valid' on table 'Tariff' with the annotation 'CustomTemporal:WithoutOverlaps' of EFCore.ComplexIndexes 5.x.");
        StringAssert.Contains(refused.Message, "issues/28");
    }
}
